// QuickNodeConsoleServiceServer is the server API for QuickNodeConsoleService service.
// All implementations should embed UnimplementedQuickNodeConsoleServiceServer
// for forward compatibility.
//
// QuickNode Console API. Manage RPC endpoints, view billing, usage metrics,
// rate limits, security settings, and supported chains. Requires
// QUICKNODE_API_KEY with CONSOLE_REST permission.
type QuickNodeConsoleServiceServer interface {
	// List all supported blockchain chains and networks.
	ListChains(context.Context, *ListChainsRequest) (*ListChainsResponse, error)
	// List all RPC endpoints in the account.
	ListEndpoints(context.Context, *ListEndpointsRequest) (*ListEndpointsResponse, error)
	// Create a new RPC endpoint for a specific chain and network.
	CreateEndpoint(context.Context, *CreateEndpointRequest) (*Endpoint, error)
	// Get details of a specific RPC endpoint by ID.
	GetEndpoint(context.Context, *GetEndpointRequest) (*Endpoint, error)
	// Update an existing RPC endpoint (name, add-ons).
	UpdateEndpoint(context.Context, *UpdateEndpointRequest) (*Endpoint, error)
	// Delete (archive) an RPC endpoint by ID.
	DeleteEndpoint(context.Context, *DeleteEndpointRequest) (*DeleteEndpointResponse, error)
	// Pause or unpause an RPC endpoint.
	UpdateEndpointStatus(context.Context, *UpdateEndpointStatusRequest) (*Endpoint, error)
	// Get performance metrics for an endpoint (method calls, response times, status breakdowns).
	GetEndpointMetrics(context.Context, *GetEndpointMetricsRequest) (*GetEndpointMetricsResponse, error)
	// Get request logs for an endpoint within a time range.
	GetEndpointLogs(context.Context, *GetEndpointLogsRequest) (*GetEndpointLogsResponse, error)
	// Get detailed information about a specific logged request.
	GetEndpointLogDetails(context.Context, *GetEndpointLogDetailsRequest) (*LogDetail, error)
	// Get total RPC usage within a time range.
	GetRPCUsage(context.Context, *GetRPCUsageRequest) (*GetRPCUsageResponse, error)
	// Get RPC usage broken down by individual endpoint.
	GetRPCUsageByEndpoint(context.Context, *GetRPCUsageRequest) (*GetRPCUsageByEndpointResponse, error)
	// Get RPC usage broken down by RPC method.
	GetRPCUsageByMethod(context.Context, *GetRPCUsageRequest) (*GetRPCUsageByMethodResponse, error)
	// Get RPC usage broken down by blockchain network.
	GetRPCUsageByChain(context.Context, *GetRPCUsageRequest) (*GetRPCUsageByChainResponse, error)
	// List billing invoices.
	ListInvoices(context.Context, *ListInvoicesRequest) (*ListInvoicesResponse, error)
	// List billing payments.
	ListPayments(context.Context, *ListPaymentsRequest) (*ListPaymentsResponse, error)
	// Get method-level rate limits for an endpoint.
	GetMethodRateLimits(context.Context, *GetMethodRateLimitsRequest) (*GetMethodRateLimitsResponse, error)
	// Update global rate limits (requests per second/minute/day) for an endpoint.
	UpdateRateLimits(context.Context, *UpdateRateLimitsRequest) (*UpdateRateLimitsResponse, error)
	// Create a method-level rate limit for an endpoint.
	CreateMethodRateLimit(context.Context, *CreateMethodRateLimitRequest) (*MethodRateLimit, error)
	// Update a method-level rate limit.
	UpdateMethodRateLimit(context.Context, *UpdateMethodRateLimitRequest) (*MethodRateLimit, error)
	// Delete a method-level rate limit.
	DeleteMethodRateLimit(context.Context, *DeleteMethodRateLimitRequest) (*DeleteMethodRateLimitResponse, error)
	// Get security options for an endpoint (token auth, JWT, IP allowlist, referrer, domain mask).
	GetSecurityOptions(context.Context, *GetSecurityOptionsRequest) (*SecurityOptions, error)
	// Update security options for an endpoint.
	UpdateSecurityOptions(context.Context, *UpdateSecurityOptionsRequest) (*SecurityOptions, error)
	// Create a domain mask for an endpoint.
	CreateDomainMask(context.Context, *CreateDomainMaskRequest) (*DomainMask, error)
	// Add an IP address to the endpoint allowlist.
	CreateIPAllowlist(context.Context, *CreateIPAllowlistRequest) (*IPAllowlistEntry, error)
	// Create a JWT authentication token for an endpoint.
	CreateJWT(context.Context, *CreateJWTRequest) (*JWTEntry, error)
	// Add a referrer to the endpoint allowlist.
	CreateReferrer(context.Context, *CreateReferrerRequest) (*ReferrerEntry, error)
	// Create an authentication token for an endpoint.
	CreateToken(context.Context, *CreateTokenRequest) (*TokenEntry, error)
	// Delete a domain mask from an endpoint.
	DeleteDomainMask(context.Context, *DeleteDomainMaskRequest) (*DeleteSecurityEntryResponse, error)
	// Delete an IP from the endpoint allowlist.
	DeleteIPAllowlist(context.Context, *DeleteIPAllowlistRequest) (*DeleteSecurityEntryResponse, error)
	// Delete a JWT from an endpoint.
	DeleteJWT(context.Context, *DeleteJWTRequest) (*DeleteSecurityEntryResponse, error)
	// Delete a referrer from an endpoint.
	DeleteReferrer(context.Context, *DeleteReferrerRequest) (*DeleteSecurityEntryResponse, error)
	// Delete an authentication token from an endpoint.
	DeleteToken(context.Context, *DeleteTokenRequest) (*DeleteSecurityEntryResponse, error)
	// Get tags for an endpoint.
	GetEndpointTags(context.Context, *GetEndpointTagsRequest) (*GetEndpointTagsResponse, error)
	// Create a tag for an endpoint.
	CreateEndpointTag(context.Context, *CreateEndpointTagRequest) (*EndpointTag, error)
}

