// token balances, transaction history, contract ABIs, block data, and ENS
// resolution. Also includes single-flight RPC, block timestamp lookup,
// multi-region broadcast, and Solana priority fee estimation.
// Requires QUICKNODE_ENDPOINT_URL pointing to an endpoint with these add-ons enabled.
type QuickNodeTokenNFTServiceClient interface {
	// Fetch all NFTs (ERC-721 & ERC-1155) owned by a wallet address.
	// Supports pagination and filtering by contract addresses.
	FetchNFTs(ctx context.Context, in *FetchNFTsRequest, opts ...grpc.CallOption) (*FetchNFTsResponse, error)
	// Fetch NFTs within a specific collection by contract address.
	FetchNFTsByCollection(ctx context.Context, in *FetchNFTsByCollectionRequest, opts ...grpc.CallOption) (*FetchNFTsByCollectionResponse, error)
	// Get high-level details about an NFT collection (name, description, floor price).
	FetchNFTCollectionDetails(ctx context.Context, in *FetchNFTCollectionDetailsRequest, opts ...grpc.CallOption) (*FetchNFTCollectionDetailsResponse, error)
	// Get transfer history for a specific NFT (by contract address and token ID).
	GetTransfersByNFT(ctx context.Context, in *GetTransfersByNFTRequest, opts ...grpc.CallOption) (*GetTransfersByNFTResponse, error)
	// Verify if a wallet owns specific NFTs. Returns which NFTs from the list are owned.
	VerifyNFTsOwner(ctx context.Context, in *VerifyNFTsOwnerRequest, opts ...grpc.CallOption) (*VerifyNFTsOwnerResponse, error)
	// Get ERC-20 token balances for a wallet address.
	GetWalletTokenBalance(ctx context.Context, in *GetWalletTokenBalanceRequest, opts ...grpc.CallOption) (*GetWalletTokenBalanceResponse, error)
	// Get ERC-20 token transactions for a wallet address.
	GetWalletTokenTransactions(ctx context.Context, in *GetWalletTokenTransactionsRequest, opts ...grpc.CallOption) (*GetWalletTokenTransactionsResponse, error)
	// Get token metadata (name, symbol, decimals, total supply) by contract address.
	GetTokenMetadataByContractAddress(ctx context.Context, in *GetTokenMetadataByContractAddressRequest, opts ...grpc.CallOption) (*TokenMetadata, error)
	// Get token metadata by token symbol.
	GetTokenMetadataBySymbol(ctx context.Context, in *GetTokenMetadataBySymbolRequest, opts ...grpc.CallOption) (*GetTokenMetadataBySymbolResponse, error)
	// Get transactions for a wallet address with pagination.
	GetTransactionsByAddress(ctx context.Context, in *GetTransactionsByAddressRequest, opts ...grpc.CallOption) (*GetTransactionsByAddressResponse, error)
	// Get the ABI for a verified smart contract.
	GetContractABI(ctx context.Context, in *GetContractABIRequest, opts ...grpc.CallOption) (*GetContractABIResponse, error)
	// Get all transaction receipts for a block in a single call (Single Flight RPC).
	GetReceipts(ctx context.Context, in *GetReceiptsRequest, opts ...grpc.CallOption) (*GetReceiptsResponse, error)
	// Get block data with all transaction receipts in a single call (Single Flight RPC).
	GetBlockWithReceipts(ctx context.Context, in *GetBlockWithReceiptsRequest, opts ...grpc.CallOption) (*GetBlockWithReceiptsResponse, error)
	// Get the block number at or before a given Unix timestamp.
	GetBlockFromTimestamp(ctx context.Context, in *GetBlockFromTimestampRequest, opts ...grpc.CallOption) (*GetBlockFromTimestampResponse, error)
	// Get all blocks within a Unix timestamp range.
	GetBlocksInTimestampRange(ctx context.Context, in *GetBlocksInTimestampRangeRequest, opts ...grpc.CallOption) (*GetBlocksInTimestampRangeResponse, error)
	// Resolve an ENS name to an address or reverse-resolve an address to an ENS name.
	ResolveENS(ctx context.Context, in *ResolveENSRequest, opts ...grpc.CallOption) (*ResolveENSResponse, error)
	// Broadcast a signed raw transaction across multiple geographic regions for faster propagation.
	BroadcastRawTransaction(ctx context.Context, in *BroadcastRawTransactionRequest, opts ...grpc.CallOption) (*BroadcastRawTransactionResponse, error)
	// Estimate Solana priority fees in percentiles (low/medium/high/extreme/recommended).
	// Requires a Solana endpoint with the Priority Fee API add-on.
	EstimatePriorityFees(ctx context.Context, in *EstimatePriorityFeesRequest, opts ...grpc.CallOption) (*EstimatePriorityFeesResponse, error)
}

